const dataStr =  $json.timestamp;
const data = new Date(dataStr);

const ano = data.getFullYear()
const mes = data.getMonth() + 1

const primeiroDiaDoMes = new Date(ano, data.getMonth(), 1)
const diaDoMes = data.getDate()

const semana_do_mes = Math.ceil(
  (diaDoMes + primeiroDiaDoMes.getDay()) / 7
)

return {
  json: {
    ano,
    mes,
    semana_do_mes,
  }
};

const rows = items.map(i => i.json);

if (!rows.length) {
  return [{
    json: {
      semana: null,
      empresa: null,
      total_feedbacks: 0
    }
  }];
}

const semana = rows[0].week;
const empresa = $('Processar Cada Empresa').first().json.name;
const slug_empresa = rows[0].company_slug;
const total = rows.length;

const countBy = (key) =>
  rows.reduce((acc, r) => {
    const v = r[key] ?? "não informado";
    acc[v] = (acc[v] || 0) + 1;
    return acc;
  }, {});

const tipos = countBy("classified_type");
const sentimentos = countBy("sentiment");
const setores = countBy("department");
const temas = countBy("main_theme");
const criticidade = countBy("criticality");

const criticos = rows.filter(r => r.criticality === "alta");

const resumos = rows.map(r => r.executive_summary).filter(Boolean);
const insights = rows.map(r => r.actionable_insight).filter(Boolean);

return [{
  json: {
    semana,
    empresa,
    slug_empresa,
    total_feedbacks: total,
    tipos,
    sentimentos,
    setores,
    temas,
    criticidade,
    quantidade_criticos: criticos.length,
    resumos,
    insights
  }
}];

return items.map(item => {
  const d = item.json;

  const toText = (v) => {
    if (!v) return "";
    if (typeof v === "string") return v;
    try {
      return JSON.stringify(v, null, 2);
    } catch {
      return String(v);
    }
  };

  const prompt = `Com base nos dados agregados abaixo, gere um RELATÓRIO SEMANAL EXECUTIVO.
Retorne EXCLUSIVAMENTE um JSON válido, sem texto adicional.

Contexto:
- Os dados são de feedbacks anônimos de colaboradores
- O relatório será enviado para gestores
- Linguagem clara, analítica, simples e profissional
- Evite termos técnicos excessivos
- Não invente dados

Dados da semana:
Semana: ${d.semana ?? "N/A"}
Total de feedbacks: ${d.total_feedbacks ?? 0}

Distribuição por tipo de feedback:
${toText(d.tipos)}

Distribuição por sentimento:
${toText(d.sentimentos)}

Distribuição por setor:
${toText(d.setores)}

Temas principais mais recorrentes:
${toText(d.temas)}

Distribuição por criticidade:
${toText(d.criticidade)}

Quantidade de feedbacks com criticidade alta:
${d.quantidade_criticos ?? 0}

Resumos executivos individuais:
${toText(d.resumos)}

Insights individuais:
${toText(d.insights)}

Tarefas obrigatórias:
1. Criar resumo executivo geral da semana
2. Interpretar o clima geral da empresa com base nos sentimentos
3. Identificar padrões e temas recorrentes relevantes
4. Apontar pontos de atenção para a liderança
5. Destacar aspectos positivos, se existirem
6. Gerar recomendações práticas
7. Indicar o sentimento predominante da semana
8. Identificar o setor mais citado

Formato de saída (JSON obrigatório):
{
  "resumo_executivo_geral": "",
  "visao_geral": "",
  "analise_sentimentos": "",
  "temas_recorrentes": [
    {
      "tema": "",
      "quantidade": ""
    }
  ],
  "pontos_atencao": "",
  "pontos_positivos": "",
  "recomendacoes": "",
  "conclusao": "",
  "sentimento_predominante": "",
  "setor_mais_citado": ""
}`;

  return {
    json: {
      model: "openai/gpt-4o-mini",
      temperature: 0.3,
      messages: [
        {
          role: "system",
          content: "Você é um analista especialista em clima organizacional, cultura corporativa e relatórios executivos para gestores de pequenas empresas."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      empresa: d.empresa,
      semana: d.semana,
    }
  };
});

const content = $json.choices[0].message.content;
const context = $('Montar Prompt para IA').first().json;

// remove possíveis ```json ou ``` que a IA possa ter colocado
const cleaned = content
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(cleaned);

parsed.empresa = context.empresa;
parsed.semana = context.semana;

return [
  {
    json: parsed
  }
];

// Dados Base
const analise = $input.first().json;
const contagem = $('Agregar Métricas Semanais').item.json;

// Tabela de tema - HTML
const temas = analise.temas_recorrentes ?? [];

temas.sort((a, b) => (b.quantidade ?? 0) - (a.quantidade ?? 0));

let rows = "";

for (const t of temas) {
  rows += `
    <tr>
      <td>${t.tema}</td>
      <td>${t.quantidade}</td>
    </tr>
  `;
}

const tabela_temas_html = `
<table>
  <thead>
    <tr>
      <th>Tema Principal</th>
      <th style="width: 100px;">Quantidade</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>
`;

// Feedbacks Individuais - HTML
let feedbacks = $('Buscar Feedbacks Semanais').all();

feedbacks = feedbacks.filter(item => item.json.feedback || item.json.executive_summary);

const ordemCriticidade = { "alta": 3, "media": 2, "baixa": 1, "N/A": 0 };

const coresBorda = {
  "alta": "#f87171", 
  "media": "#fbbf24", 
  "baixa": "#34d399",
  "N/A": "#e2e8f0" 
};

feedbacks.sort((a, b) => {
  const c1 = ordemCriticidade[a.json.criticidade] ?? 0;
  const c2 = ordemCriticidade[b.json.criticidade] ?? 0;
  return c2 - c1;
});

let feedbacks_html = "";
let contador = 1;

for (const item of feedbacks) {
  const f = item.json ?? {};

  const feedback_original = f.feedback?.trim();
  const resumo = f.executive_summary?.trim();

  if (!feedback_original && !resumo) continue;

  const setor = f.department || 'Não informado';
  const tema = f.main_theme || 'Não classificado';
  const sentimento = f.sentiment || 'N/A';
  const criticidade = f.criticality || 'N/A';
  const tipo = f.classified_type || 'N/A';

  const corBorda = coresBorda[criticidade] || "#e2e8f0";

  feedbacks_html += `
    <div class="feedback-item">
      <div class="feedback-header">🗨️ Feedback #${contador}</div>

      <div class="feedback-meta">
        <span><b>Setor:</b> ${setor}</span>
        <span><b>Tema:</b> ${tema}</span>
        <span><b>Sentimento:</b> ${sentimento}</span>
        <span><b>Criticidade:</b> ${criticidade}</span>
        <span><b>Tipo:</b> ${tipo}</span>
      </div>

      <div class="feedback-resumo">
        ${resumo || '<i>Resumo não disponível</i>'}
      </div>

      <div class="feedback-original" style="border-left: 4px solid ${corBorda};">
        "${feedback_original || ''}"
      </div>
    </div>
  `;

  contador++;
}

if (!feedbacks_html) {
  feedbacks_html = `<p><i>Nenhum feedback individual encontrado para esta semana.</i></p>`;
}

// Retorno final para o HTML
return [{
  json: {
    empresa: contagem.empresa,
    semana: contagem.semana,
    data_hoje: new Date().toLocaleDateString('pt-BR'),

    total_feedbacks: contagem.total_feedbacks,
    quantidade_criticos: contagem.quantidade_criticos,

    sentimento_predominante: analise.sentimento_predominante,
    setor_mais_citado: analise.setor_mais_citado,

    resumo_executivo_geral: analise.resumo_executivo_geral,
    pontos_atencao: analise.pontos_atencao,
    pontos_positivos: analise.pontos_positivos,
    conclusao: analise.conclusao,

    recomendacoes_html: analise.recomendacoes
      .replace(/^(\d+\.\s*)/, '• ')
      .replace(/\s\d+\.\s*/g, '<br>• '),

    tabela_temas_html,
    feedbacks_html
  }
}];
